 using System;
+using System.Data;
+using System.Text;
+using System.Text.RegularExpressions;
 using System.Web.UI;
+using InformationWebObject;
+using WebGlobal;

 namespace InformationWeb.Controls.Information.Khoa
 {
     public partial class SectionKhoaPhong : System.Web.UI.UserControl
     {
+        private const int KhoiNoiCategoryId = 367;
+        private const int KhoiNgoaiCategoryId = 368;
+        private const int KhoiHoTroCategoryId = 369;
+        private const int DepartmentTop = 50;
+
         protected void Page_Load(object sender, EventArgs e)
         {
         }
+
+        protected int KhoiNoiCount
+        {
+            get { return GetBlockCount(KhoiNoiCategoryId); }
+        }
+
+        protected int KhoiNgoaiCount
+        {
+            get { return GetBlockCount(KhoiNgoaiCategoryId); }
+        }
+
+        protected int KhoiHoTroCount
+        {
+            get { return GetBlockCount(KhoiHoTroCategoryId); }
+        }
+
+        protected string RenderKhoiNoiCards()
+        {
+            return RenderDepartmentCards(KhoiNoiCategoryId, "+");
+        }
+
+        protected string RenderKhoiNgoaiCards()
+        {
+            return RenderDepartmentCards(KhoiNgoaiCategoryId, "+");
+        }
+
+        protected string RenderKhoiHoTroCards()
+        {
+            return RenderDepartmentCards(KhoiHoTroCategoryId, "+");
+        }
+
+        private int GetBlockCount(int categoryId)
+        {
+            DataTable dt = GetDepartmentData(categoryId);
+            return dt == null ? 0 : dt.Rows.Count;
+        }
+
+        private DataTable GetDepartmentData(int categoryId)
+        {
+            string cacheKey = "KHOA_PHONG_BLOCK_" + ResManager.CurrentLanguageID + "_" + categoryId;
+            DataTable dt = Cache[cacheKey] as DataTable;
+            if (dt != null) return dt;
+
+            try
+            {
+                INFO_Information info = new INFO_Information();
+                dt = info.GetDataTable(
+                    "INFO_Information_HOS_NewsM",
+                    "@LanguageID", ResManager.CurrentLanguageID,
+                    "@NodeID", categoryId,
+                    "@Top", DepartmentTop
+                );
+
+                if (dt != null)
+                {
+                    Cache.Insert(
+                        cacheKey,
+                        dt,
+                        null,
+                        DateTime.Now.AddMinutes(10),
+                        System.Web.Caching.Cache.NoSlidingExpiration
+                    );
+                }
+            }
+            catch
+            {
+                dt = null;
+            }
+
+            return dt;
+        }
+
+        private string RenderDepartmentCards(int categoryId, string placeholderIcon)
+        {
+            DataTable dt = GetDepartmentData(categoryId);
+            if (dt == null || dt.Rows.Count == 0)
+                return "<div class=\"dept-empty\">Đang cập nhật dữ liệu.</div>";
+
+            StringBuilder html = new StringBuilder();
+            foreach (DataRow row in dt.Rows)
+            {
+                string title = GetValue(row, "Title");
+                if (string.IsNullOrEmpty(title)) continue;
+
+                string description = GetValue(row, "Description");
+                if (string.IsNullOrEmpty(description))
+                    description = GetValue(row, "Brief");
+
+                string subtitle = "";
+                string tag = "";
+                SplitKeyword(GetValue(row, "Keyword"), out subtitle, out tag);
+
+                string image = GetDepartmentImage(row);
+                string link = GetDepartmentUrl(row, categoryId);
+                string icon = string.IsNullOrEmpty(placeholderIcon) ? "+" : placeholderIcon;
+
+                html.AppendLine("<a class=\"dept-card\" href=\"" + HtmlAttribute(link) + "\">");
+                html.AppendLine("  <div class=\"card-image\">");
+                if (string.IsNullOrEmpty(image))
+                {
+                    html.AppendLine("    <div class=\"placeholder-img\">" + HtmlEncode(icon) + "</div>");
+                }
+                else
+                {
+                    html.AppendLine("    <img src=\"" + HtmlAttribute(image) + "\" alt=\"" + HtmlAttribute(title) + "\" class=\"card-photo lazy-fade\" loading=\"lazy\" />");
+                }
+                html.AppendLine("    <div class=\"card-image-overlay\"></div>");
+                html.AppendLine("    <div class=\"card-icon-overlay\"><span>" + HtmlEncode(icon) + "</span></div>");
+                html.AppendLine("  </div>");
+                html.AppendLine("  <div class=\"card-body\">");
+                html.AppendLine("    <div class=\"card-meta-row\">");
+                if (!string.IsNullOrEmpty(subtitle))
+                    html.AppendLine("      <div class=\"card-subtitle\">" + HtmlEncode(subtitle) + "</div>");
+                if (!string.IsNullOrEmpty(tag))
+                    html.AppendLine("      <span class=\"card-tag-inline\">" + HtmlEncode(tag) + "</span>");
+                html.AppendLine("    </div>");
+                html.AppendLine("    <h3>" + HtmlEncode(title) + "</h3>");
+                html.AppendLine("    <p class=\"card-desc\">" + HtmlEncode(StripHtml(description, 180)) + "</p>");
+                html.AppendLine("  </div>");
+                html.AppendLine("</a>");
+            }
+
+            if (html.Length == 0)
+                return "<div class=\"dept-empty\">Đang cập nhật dữ liệu.</div>";
+
+            return html.ToString();
+        }
+
+        private string GetDepartmentUrl(DataRow row, int fallbackCategoryId)
+        {
+            string slug = GetValue(row, "InformationLink");
+            if (string.IsNullOrEmpty(slug)) return "#";
+
+            string categoryLink = GetValue(row, "CategoryLink");
+            if (string.IsNullOrEmpty(categoryLink))
+                categoryLink = GetDefaultCategoryLink(fallbackCategoryId);
+
+            categoryLink = categoryLink.Trim().Trim('/');
+            slug = slug.Trim().Trim('/');
+
+            if (ResManager.CurrentLanguageID == 2)
+                return "/en/" + categoryLink + "/" + Server.UrlEncode(slug);
+
+            return "/" + categoryLink + "/" + Server.UrlEncode(slug);
+        }
+
+        private string GetDefaultCategoryLink(int categoryId)
+        {
+            if (categoryId == KhoiNoiCategoryId) return "khoi-noi";
+            if (categoryId == KhoiNgoaiCategoryId) return "khoi-ngoai";
+            if (categoryId == KhoiHoTroCategoryId) return "khoi-ho-tro";
+            return "";
+        }
+
+        private string GetDepartmentImage(DataRow row)
+        {
+            if (row == null) return "";
+
+            int id = 0;
+            string idText = GetValue(row, "InformationID");
+            if (string.IsNullOrEmpty(idText))
+                idText = GetValue(row, "InformationId");
+            int.TryParse(idText, out id);
+
+            string image = GetValue(row, "ThumbImageSub");
+            if (string.IsNullOrEmpty(image))
+                image = GetValue(row, "ThumbImageList");
+            if (string.IsNullOrEmpty(image))
+                image = GetValue(row, "ThumbImage");
+
+            if (string.IsNullOrEmpty(image)) return "";
+            if (image.StartsWith("/") || image.StartsWith("http")) return image;
+
+            string s = "000000" + id;
+            string sub = "Information" + s.Substring(s.Length - 6);
+            return WebGlobal.InformationThumbDirectory + "/" + sub + "/" + image;
+        }
+
+        private void SplitKeyword(string rawKeyword, out string subtitle, out string tag)
+        {
+            subtitle = "";
+            tag = "";
+
+            if (string.IsNullOrEmpty(rawKeyword)) return;
+
+            string[] parts = rawKeyword.Split(new char[] { '|', ';' }, StringSplitOptions.RemoveEmptyEntries);
+            if (parts.Length < 2 && rawKeyword.IndexOf(",") >= 0)
+                parts = rawKeyword.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
+
+            if (parts.Length >= 2)
+            {
+                subtitle = parts[0].Trim();
+                tag = parts[1].Trim();
+            }
+            else
+            {
+                tag = rawKeyword.Trim();
+            }
+        }
+
+        private string GetValue(DataRow row, string columnName)
+        {
+            if (row == null || row.Table == null || string.IsNullOrEmpty(columnName)) return "";
+
+            foreach (DataColumn column in row.Table.Columns)
+            {
+                if (string.Equals(column.ColumnName, columnName, StringComparison.OrdinalIgnoreCase))
+                    return row[column] == DBNull.Value || row[column] == null ? "" : row[column].ToString();
+            }
+
+            return "";
+        }
+
+        private string StripHtml(string input, int maxLen)
+        {
+            if (string.IsNullOrEmpty(input)) return "";
+
+            string text = Regex.Replace(input, "<.*?>", " ");
+            text = Regex.Replace(text, @"\s+", " ").Trim();
+
+            if (maxLen > 0 && text.Length > maxLen)
+                text = text.Substring(0, maxLen).Trim() + "...";
+
+            return text;
+        }
+
+        private string HtmlEncode(string value)
+        {
+            return Server.HtmlEncode(value ?? "");
+        }
+
+        private string HtmlAttribute(string value)
+        {
+            return Server.HtmlEncode(value ?? "");
+        }
     }
 }
